source_raw_tex:
\eqalignno{\theta(C\cap(E\times F))
&\le\theta(W\cap(E\times F))
=\lambda_0(W\cap(E\times F))\cr
\noalign{\noindent (where $\lambda_0$ is the primitive product measure)}
&\le\lambda W.\cr}

